// Helper: create a simple TK mission
function tk(id: string, num: number, title: string, cat: "tk-adab"|"tk-pra-literasi"|"tk-pola"|"tk-visual"|"tk-kreativitas", type: MissionType, story: string, instruction: string, opts: {label:string,emoji?:string}[], correctIdx: number, explanation: string, hints: string[], point: number, adab?: number, adabFb?: string, boss?: boolean): any {
  const options = opts.map((o,i) => ({id:String.fromCharCode(97+i), label:o.label, emoji:o.emoji, ...(i===correctIdx?{feedback:"Tepat!"}:{})}));
  return {id,num,title,difficulty:"tk",gradeRange:"TK",category:cat,missionType:type,story,instruction,options,correctAnswer:String.fromCharCode(97+correctIdx),explanation,hintLevels:hints,basePoint:point,...(adab?{adabBonus:adab}:{}),...(adabFb?{adabFeedback:adabFb}:{}),...(boss?{isBossMission:true}:{})};
}
